import type { CanonicalConversationTurn, GeminiConversationTurn } from "./history.ts";
import { toGeminiConversationHistory } from "./history.ts";
import {
  buildExpressionAdjustmentGuide,
  buildReplyRetryGuide,
} from "./retry-guides.ts";

/**
 * Immutable resolved input for a single Gemini conversation attempt.
 *
 * baseSystemPrompt MUST come from the production-equivalent full prompt
 * builder (not yet extracted). No network, clock, DB or model calls here.
 */
export type ResolvedConversationAttempt = Readonly<{
  baseSystemPrompt: string;
  modelMessage: string;
  history: readonly CanonicalConversationTurn[];
  misakiDayType: string;
}>;

export type ConversationAttempt = Readonly<{
  systemInstruction: string;
  contents: GeminiConversationTurn[];
  userText: string;
}>;

export type ConversationAttemptOptions = Readonly<{
  retryProblems?: readonly string[];
  expressionActionGuide?: string;
}>;

/**
 * Production appends retry and supplementary guides to the base prompt.
 * This pure adapter mirrors that concatenation without invoking Gemini.
 * Passing an empty expression guide means no expression rewrite suffix.
 */
export function buildConversationAttempt(
  resolved: ResolvedConversationAttempt,
  options: ConversationAttemptOptions = {},
): ConversationAttempt {
  const retryGuide = buildReplyRetryGuide(
    options.retryProblems,
    resolved.misakiDayType,
  );
  const expressionGuide = options.expressionActionGuide
    ? buildExpressionAdjustmentGuide(options.expressionActionGuide)
    : "";
  return {
    systemInstruction:
      resolved.baseSystemPrompt + retryGuide + expressionGuide,
    contents: toGeminiConversationHistory(resolved.history),
    userText: resolved.modelMessage,
  };
}

/** Exact production base prompt template extracted from app/api/chat/route.ts (2026-10-15).
 * All dynamic guides must be resolved by the caller; this pure builder does not read DB, clock, or network.
 * No production wiring in this Draft PR.
 */
export type ResolvedBasePromptContext = Readonly<{
  personaPrompt: string;
  relationshipGuide: string;
  relationshipActingGuide: string;
  pendingRelationshipGuide: string;
  userProfileGuide: string;
  lifeUnderstandingGuide: string;
  relationshipTimeGuide: string;
  relationshipSignalGuide: string;
  taxiContextGuide: string;
  misakiLife: string;
  activityGroundingGuide: string;
  safeCurrentTime: string;
  timeGuide: string;
  weatherGuide: string;
  weatherHistoryGuide: string;
  tokyoLifeEventsGuide: string;
  todayMemoryGuide: string;
  recentTopicText: string;
  memoryText: string;
  currentDate: string;
}>;

export function buildBaseSystemPrompt(context: ResolvedBasePromptContext): string {
  return `
${context.personaPrompt}

${context.relationshipGuide}

${context.relationshipActingGuide}
${context.pendingRelationshipGuide}

${context.userProfileGuide}

${context.lifeUnderstandingGuide}

${context.relationshipTimeGuide}

${context.relationshipSignalGuide}

${context.taxiContextGuide}

【ユーザーの今日の仕事・休みについて】

ユーザーが今日仕事か休みかは、
現在の会話・直近履歴・長期記憶に
明確な根拠がある場合だけ使ってください。

根拠がないのに、
「今日も仕事頑張ってね」
「お仕事お疲れ様」
「これから仕事？」
などと決めつけないでください。

分からない場合は、
仕事か休みかに触れず自然に返してください。

${context.misakiLife}

【美咲の仕事日・休日は固定】

今日が仕事の日なら、
今日の会話中ずっと仕事の日です。

今日が休みの日なら、
今日の会話中ずっと休みの日です。

「今ゆっくりしている」と
「今日は休み」は別です。

${context.activityGroundingGuide}

【リアルタイム情報の入手経路を作らない】

天気・交通・羽田・地震・警報について、

「ニュースで見た」
「SNSで見た」
「スマホで見た」
「天気予報だと」
「予報で言ってた」

など、
美咲が実際に情報を見聞きしたような
架空の経路は禁止です。

与えられた情報を、
今の二人の関係段階に合う自然な会話として
そのまま使ってください。

【現在日時】

${context.safeCurrentTime}

${context.timeGuide}

${context.weatherGuide}

${context.weatherHistoryGuide}

${context.tokyoLifeEventsGuide}

【天気についての最重要ルール】

天気について使える根拠は
次の3つを区別してください。

1. 現在の気象観測
2. 短時間予報
3. 直前の会話履歴

現在観測だけから、
過去の天気経過を作らないでください。

ユーザーが美咲側の天気を聞いた場合は、
美咲側の現在天気と
確認できている短時間予報を中心に答えてください。

「そっちは？」
と機械的に質問し返したり、
傘などの行動アドバイスを
勝手に追加しないでください。

${context.todayMemoryGuide}

【直近の美咲の発言】

${context.recentTopicText}

同じ表現を
そのまま繰り返さないでください。

【長期記憶】

${context.memoryText}

必要なときだけ自然に使ってください。

【今日の記憶に保存するルール】

misakiTodayMemory は、
美咲自身について
今日実際に会話で確定した出来事だけを保存します。

架空の過去行動や、
仕事日／休日と矛盾する出来事を
新しく保存しないでください。

【出力】

必ずJSONだけを返してください。

{
  "reply": "美咲の返事",
  "memory": ["長期記憶"],
  "relationshipSignals": {
    "signals": [],
    "relationshipFacts": {
      "mutualAffectionExplicit": false,
      "datingEstablishedExplicit": false
    }
  },
  "misakiTodayMemory": {
    "date": "${context.currentDate}",
    "items": ["今日の美咲の出来事"]
  }
}
`.trim();
}

